 "content": "def transform(grid):
    # Isolated object of color 7 is a palette key: recolor the matching large irregular 6-shape to 7.
    # In the examples, a small color marker above the irregular 0-shape changes it to the template color 6.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Connected components of non-background cells; identify singleton/short marker color and large shape.
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]==bg or (r,c) in seen: continue
       col=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
       while stack:
        y,x=stack.pop(); cells.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         yy,xx=y+dy,x+dx
         if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
          seen.add((yy,xx)); stack.append((yy,xx))
       comps.append((col,cells))
    # Find the smallest isolated component as color key; recolor largest other component to that color.
    bycol={}
    for col,cells in comps: bycol.setdefault(col,[]).append(cells)
    # Key is a single-cell color marker, target is the largest component of a different color.
    keys=[(col,cells) for col,cells in comps if len(cells)<=3]
    if keys:
      keycol=keys[0][0]
      targets=[(len(cells),col,cells) for col,cells in comps if col!=keycol]
      if targets:
       _,old,cells=max(targets)
       for r,c in cells: out[r][c]=keycol
    return out
"
}

